            if key not in event:
                raise Invalid('field')
            value = event[key]
            if kind == POS:
                if not _is_u32(value):
                    raise Invalid('field')
            elif kind == NAME:
                if not _is_name(value):
                    raise Invalid('field')
            elif kind == TEXT:
                if type(value) is not str:
                    raise Invalid('field')
                try:
                    policy_bytes += len(value.encode('utf-8'))
                except UnicodeEncodeError:
                    raise Invalid('field')
            elif kind == WIRE_T:
                if value is not None and (type(value) is not str
                                          or len(value) > MAX_WIRE):
                    raise Invalid('field')
            elif kind == PAIR:
                if not _is_pair(value):
                    raise Invalid('field')
            elif not _is_unit(value):
                raise Invalid('field')
        if op == 'stage':
            stages += 1
            text = event['policy']
            if text in _parse_cache:
                result = _parse_cache[text]
            else:
                try:
                    result = parse_policy(text)
                except Exception:
                    result = None
                if len(_parse_cache) < 4096:
                    _parse_cache[text] = result
            if result is not None:
                atoms += result.atoms
                symbols += result.symbols
                parsed[index] = result
        index += 1
    return policy_bytes, stages, atoms, symbols, parsed


# --------------------------------------------------------------------------
# outcome serialisation (compact, ASCII only)
# --------------------------------------------------------------------------
_B_OK = b'{"ok":true}'
_B_ERR = b'{"error":"rejected"}'
_B_ALLOW_T = b'{"ok":true,"allow":true}'
_B_ALLOW_F = b'{"ok":true,"allow":false}'


def serialize(outcome):
    tag = outcome[0]
    if tag == RAW:
        return outcome[1]
    if tag == OK:
        return _B_OK
    if tag == ERR:
        return _B_ERR
    if tag == STATE:
        return b'{"ok":true,"epoch":%d,"state":%d}' % (outcome[1], outcome[2])
    if tag == ALLOW:
        return _B_ALLOW_T if outcome[1] else _B_ALLOW_F
    if tag == WIRE:
        return b'{"ok":true,"wire":"' + outcome[1].encode() + b'"}'
    head = b'{"ok":true,"epoch":%d,"image":' % outcome[1]
    return head + _dumps(outcome[2], separators=(',', ':')).encode() + b'}'


class Writer(object):
    """Bounded chunked writer for the single response object."""

    def __init__(self, stream, chunk=1 << 20):
        self.stream = stream
        self.chunk = chunk
        self.parts = []
        self.size = 0

    def push(self, block):
        self.parts.append(block)
        self.size += len(block)
        if self.size >= self.chunk:
            self.flush()

    def flush(self):
        if self.parts:
            self.stream.write(b''.join(self.parts))
            self.parts = []
            self.size = 0


def replay(agent, job, parsed, writer):
    dispatch = agent.event
    push = writer.push
    index = 0
    separator = b''
    for event in job['events']:
        try:
            outcome = dispatch(event, parsed.get(index))
        except Exception:
            outcome = (ERR,)
        push(separator)
        push(serialize(outcome))
        separator = b','
        index += 1


def run(data, writer):
    try:
        jobs = decode(data)
    except Invalid:
        writer.push(b'{"error":"invalid"}')
        return
    except Exception:
        writer.push(b'{"error":"invalid"}')
        return
    states = []
    total_events = 0
    total_bytes = 0
    total_stages = 0
    total_atoms = 0
    total_symbols = 0
    for job in jobs:
        try:
            policy_bytes, stages, atoms, symbols, parsed = validate(job)
        except Invalid:
            states.append(None)
            continue
        except Exception:
            states.append(None)
            continue
        total_events += len(job['events'])
        total_bytes += policy_bytes
        total_stages += stages
        total_atoms += atoms
        total_symbols += symbols
        states.append(parsed)
    if (total_events > MAX_EVENTS or total_bytes > MAX_POLICY_BYTES
            or total_stages > MAX_STAGES or total_atoms > MAX_ATOMS
            or total_symbols > MAX_SYMBOLS):
        writer.push(b'{"error":"invalid"}')
        return
    writer.push(b'{"results":[')
    first = True
    for job, parsed in zip(jobs, states):
        if not first:
            writer.push(b',')
        first = False
        if parsed is None:
            writer.push(b'{"error":"invalid"}')
            continue
        try:
            agent = Agent(job['services'], job['limits'])
        except Exception:
            writer.push(b'{"error":"invalid"}')
            continue
        writer.push(b'{"events":[')
        try:
            replay(agent, job, parsed, writer)
        except Exception:
            # Nothing may be retracted once written; keep the array valid.
            writer.push(b'{"error":"rejected"}]}')
            continue
        writer.push(b']}')
    writer.push(b']}')


def main():
    out = Writer(sys.stdout.buffer)
    try:
        data = sys.stdin.buffer.read(MAX_INPUT + 1)
    except Exception:
        data = b''
    try:
        run(data, out)
    except Exception:
        out.parts = []
        out.size = 0
        out.push(b'{"error":"invalid"}')
    out.flush()
    try:
        sys.stdout.buffer.flush()
        sys.stdout.flush()
    except Exception:
        pass
    os._exit(0)


